package com.foodbridge.listing;
import jakarta.persistence.*;import java.math.BigDecimal;import java.time.LocalDateTime;
@Entity @Table(name="retail_listings") public class RetailListing {
    @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Column(nullable=false) private String name;@Column(length=1000) private String description;@Column(nullable=false,precision=10,scale=2) private BigDecimal originalPrice;@Column(nullable=false,precision=10,scale=2) private BigDecimal salePrice;@Column(nullable=false) private int availableQuantity;@Column(nullable=false) private String pickupLocation;@Column(nullable=false) private LocalDateTime safetyCutoff;@Column(nullable=false) private boolean active;
    protected RetailListing(){} public RetailListing(String name,String description,BigDecimal originalPrice,BigDecimal salePrice,int quantity,String location,LocalDateTime cutoff,boolean active){this.name=name;this.description=description;this.originalPrice=originalPrice;this.salePrice=salePrice;this.availableQuantity=quantity;this.pickupLocation=location;this.safetyCutoff=cutoff;this.active=active;}
    public Long getId(){return id;}public String getName(){return name;}public String getDescription(){return description;}public BigDecimal getOriginalPrice(){return originalPrice;}public BigDecimal getSalePrice(){return salePrice;}public int getAvailableQuantity(){return availableQuantity;}public String getPickupLocation(){return pickupLocation;}public LocalDateTime getSafetyCutoff(){return safetyCutoff;}public boolean isActive(){return active;}public void setAvailableQuantity(int q){availableQuantity=q;}public void setActive(boolean a){active=a;}public boolean isPurchasable(){return active&&availableQuantity>0&&LocalDateTime.now().isBefore(safetyCutoff);}
}

